-- Reproduce the real legacy shared trigger, absent from the older minimal fixture.
CREATE OR REPLACE FUNCTION fixture_child_sync_responsible() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.assigned_to IS NULL THEN NEW.assigned_to:=NEW.owner_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_sync_responsible BEFORE INSERT ON public.people_documents FOR EACH ROW EXECUTE FUNCTION fixture_child_sync_responsible();
CREATE TRIGGER trg_sync_responsible BEFORE INSERT ON public.people_goals FOR EACH ROW EXECUTE FUNCTION fixture_child_sync_responsible();
CREATE TRIGGER trg_sync_responsible BEFORE INSERT ON public.people_one_on_ones FOR EACH ROW EXECUTE FUNCTION fixture_child_sync_responsible();
CREATE TRIGGER trg_sync_responsible BEFORE INSERT ON public.people_reviews FOR EACH ROW EXECUTE FUNCTION fixture_child_sync_responsible();
CREATE TRIGGER trg_sync_responsible BEFORE INSERT ON public.people_incidents FOR EACH ROW EXECUTE FUNCTION fixture_child_sync_responsible();
CREATE TRIGGER trg_sync_responsible BEFORE INSERT ON public.people_allocations FOR EACH ROW EXECUTE FUNCTION fixture_child_sync_responsible();
